/* global Bare */
module.exports = sleep_watch
module.exports.detect_system = detect_system

const load = eval('require') // node / bare only modules, kept out of browser bundles

// const on = sleep_watch({ interval, limit })
// on({ wakeup, sleep }) starts watching, on() stops, on({ wakeup, sleep }) again starts again
// - sleep() runs right before the machine sleeps, where the system tells us (see SYSTEMS), the machine waits till it resolves (5s max)
// - wakeup({ gap, at, announced }) runs after the process was frozen (laptop sleep, hibernate, a paused vm). its the last resort
//   and works everywhere (bare and node, not browsers): a timer ticks every `interval` ms, a tick more than `limit` ms after the one
//   before means the process was frozen for `gap` ms, `at` is Date.now() of that late tick. `announced` says if sleep() ran before,
//   false means we missed the sleep (or there was none, a big clock change or a blocked event loop look the same)
const SYSTEMS = {
  'linux-systemd': watch_logind,
  linux: todo, // TODO: linux without systemd usually has elogind, it should send the same signal but its tools may be named differently
  mac: todo, // TODO: needs native code (IOKit)
  windows: todo, // TODO: needs native code (WM_POWERBROADCAST)
  mobile: todo, // TODO: bare on android / ios emits a suspend event
  unknown: todo
}

function sleep_watch ({ interval = 100, limit = 2000 } = {}) {
  const system = detect_system()
  const state = { handlers: null, timer: null, last: 0, announced: false, stop_system: null }
  return on

  function on (handlers) {
    if (state.timer) clearInterval(state.timer)
    state.stop_system?.()
    state.stop_system = null
    state.timer = null
    state.handlers = handlers || null
    if (!handlers) return
    state.last = Date.now()
    state.announced = false
    state.timer = setInterval(check_time, interval)
    state.timer.unref() // watching alone shouldnt keep the process running
    if (handlers.sleep) state.stop_system = SYSTEMS[system](before_sleep)
  }
  function check_time () {
    const now = Date.now()
    const gap = now - state.last
    state.last = now
    if (gap <= limit) return
    const announced = state.announced
    state.announced = false
    state.handlers.wakeup?.({ gap, at: now, announced })
  }
  async function before_sleep () {
    state.announced = true
    await state.handlers.sleep()
  }
}

// linux, systemd, bare or node. logind sends PrepareForSleep (true,) right before sleeping and (false,) after waking up, and waits
// for whoever holds a "delay" lock (5s max by default) before it really sleeps. the lock is held as long as a `cat` runs, so it goes
// away when we close its stdin or our process dies, it never blocks sleep forever
function watch_logind (before_sleep) {
  const state = { lock: null, rest: '' }
  let spawn
  try {
    spawn = load(typeof Bare === 'undefined' ? 'child_process' : 'bare-subprocess').spawn
  } catch {
    return todo()
  }
  const monitor = spawn('gdbus', ['monitor', '--system', '--dest', 'org.freedesktop.login1', '--object-path', '/org/freedesktop/login1'], { stdio: ['ignore', 'pipe', 'ignore'] })
  monitor.on('error', stop) // no gdbus, the time check is all there is
  monitor.unref()
  monitor.stdout.unref?.() // on node the pipes keep the process running too, bare streams dont have unref
  monitor.stdout.on('data', on_signal)
  take_lock()
  return stop
  function on_signal (data) {
    const lines = (state.rest + data).split('\n')
    state.rest = lines.pop()
    for (const line of lines) {
      if (line.includes('PrepareForSleep (true,)')) before_sleep().finally(release_lock)
      if (line.includes('PrepareForSleep (false,)')) take_lock()
    }
  }
  function take_lock () {
    release_lock()
    state.lock = spawn('systemd-inhibit', ['--what=sleep', '--mode=delay', '--who=datashell', '--why=stop bots before sleep', 'cat'], { stdio: ['pipe', 'ignore', 'ignore'] })
    state.lock.on('error', release_lock)
    state.lock.unref()
    state.lock.stdin.unref?.()
  }
  function release_lock () {
    state.lock?.stdin.end()
    state.lock = null
  }
  function stop () {
    monitor.kill()
    release_lock()
  }
}

function todo () { return null }

function detect_system () {
  const platform = typeof Bare === 'undefined' ? process.platform : Bare.platform
  if (platform === 'linux') return has_systemd() ? 'linux-systemd' : 'linux'
  if (platform === 'darwin') return 'mac'
  if (platform === 'win32') return 'windows'
  if (platform === 'android' || platform === 'ios') return 'mobile'
  return 'unknown'
}

// the usual check, systemd creates this folder when it boots
function has_systemd () {
  try {
    return load(typeof Bare === 'undefined' ? 'fs' : 'bare-fs').existsSync('/run/systemd/system')
  } catch {
    return false
  }
}
